using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {p}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use an empty resolver so nothing is resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(Order)) ti.CreateObject = null; } }
    }
};

// Person IS resolvable here
if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");
else
    Console.WriteLine("\nPerson metadata NOT available");

// Now use a resolver that resolves nothing (returns null)
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new NullResolver()
};

if (empty.TryGetTypeInfo(typeof(Order), out _))
    Console.WriteLine("Order metadata available (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo(Order) returned false — no exception thrown ✓");

// --- Types ---
record Person(string Name, int Age);
record Order(int Id, decimal Total);

// A resolver that resolves nothing
file class NullResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

