 // 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
 //    Use a resolver that resolves nothing so the probe fails gracefully.
 var empty = new JsonSerializerOptions
 {
     TypeInfoResolver = new NullResolver()
 };

 if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
     Console.WriteLine($"\nPerson metadata available: {info!.Type.Name}");
 else
     Console.WriteLine("\nTryGetTypeInfo(Person) returned false — no exception thrown ✓");

 if (empty.TryGetTypeInfo(typeof(Order), out _))
     Console.WriteLine("Order metadata available");
 else
     Console.WriteLine("TryGetTypeInfo(Order) returned false — no exception thrown ✓");

 // --- Types ---
 record Person(string Name, int Age);
 record Order(int Id, decimal Total);

 // A resolver that resolves nothing
 file class NullResolver : IJsonTypeInfoResolver
 {
     public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
 }
